{
  "name": "@kodel-ai/opencode-plugin",
  "version": "0.2.0",
  "description": "OpenCode plugin for Kodel AI: registers chat/codex providers and the Kodel MCP server",
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "kodel",
    "kodel-ai",
    "ai-coding-agent",
    "mcp"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/kodel-ai/kodel.git"
  },
  "scripts": {
    "build": "bun build src/index.ts --target=node --format=esm --outdir dist --external @opencode-ai/plugin",
    "test": "bun test",
    "prepublishOnly": "bun run build && bun test",
    "publish:npm": "bash ../../scripts/publish-kodel-oc.sh"
  },
  "peerDependencies": {
    "@opencode-ai/sdk": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*",
    "@types/bun": "latest",
    "typescript": "^5.0.0"
  }
}
